// Function to calculate file hash using SHA-256 algorithm
void CalculateFileHash(char* filename, char* hash) {
    // Load the SHA-256 hash algorithm
    HSHA256_CTX sha256Context;
    HSHA256_Init(&sha256Context);

    // Open the file
    FILE* file = fopen(filename, "rb");

    // Read the file contents into a buffer
    uint8_t buffer[1024];
    size_t bytesRead;

    while ((bytesRead = fread(buffer, 1, sizeof(buffer), file)) > 0) {
        HSHA256_Update(&sha256Context, buffer, bytesRead);
    }

    // Finalize the hash calculation
    HSHA256_Final(&sha256Context, hash, NULL);
}

// Function to compare file hash with known good hash
bool CheckFileIntegrity(char* filename, char* knownGoodHash) {
    // Calculate the file hash
    char* calculatedHash;
    CalculateFileHash(filename, calculatedHash);

    // Compare the calculated hash with the known good hash
    return strcmp(calculatedHash, knownGoodHash) == 0;
}
```

